#!/usr/bin/env node
/**
 * Analyzes data/level-heatmaps.json (generated by generate-level-heatmaps.mjs)
 * against data/levels.json and reports:
 *
 *  1. Dead squares: cells no saved hint ever enters that also hold no grid
 *     object (gate/goal/false-goal/block/must-pass/must-cross/filter/
 *     flipping-filter/portal/goose/landmark).
 *  2. Grid-trim candidates: levels where the count of fully-empty border rows
 *     (top + bottom) equals the count of fully-empty border columns
 *     (left + right) — meaning the grid could shrink by that many cells in
 *     both dimensions while remaining square.
 *
 * Usage:
 *   node scripts/level-heatmap-report.mjs
 *   node scripts/level-heatmap-report.mjs --json   (machine-readable output)
 */
import { readFileSync } from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { collectObjectCells } from './generate-level-heatmaps.mjs';

const ROOT = new URL('..', import.meta.url).pathname;

function loadJson(relPath) {
    return JSON.parse(readFileSync(path.join(ROOT, relPath), 'utf8'));
}

function isRowEmpty(heatmap, objectCells, w, y) {
    for (let x = 1; x <= w; x++) {
        if (heatmap[y - 1][x - 1] > 0) return false;
        if (objectCells.has(`${x},${y}`)) return false;
    }
    return true;
}

function isColEmpty(heatmap, objectCells, h, x) {
    for (let y = 1; y <= h; y++) {
        if (heatmap[y - 1][x - 1] > 0) return false;
        if (objectCells.has(`${x},${y}`)) return false;
    }
    return true;
}

function countEmptyBorder(w, h, objectCells, heatmap, dim) {
    // dim: 'row' walks y from top/bottom; 'col' walks x from left/right
    if (dim === 'row') {
        let top = 0;
        for (let y = 1; y <= h; y++) { if (isRowEmpty(heatmap, objectCells, w, y)) top++; else break; }
        let bottom = 0;
        for (let y = h; y >= 1; y--) { if (isRowEmpty(heatmap, objectCells, w, y)) bottom++; else break; }
        // Guard against double-counting every row as both top and bottom on a fully-empty grid.
        if (top + bottom > h) bottom = h - top;
        return { top, bottom, total: top + bottom };
    }
    let left = 0;
    for (let x = 1; x <= w; x++) { if (isColEmpty(heatmap, objectCells, h, x)) left++; else break; }
    let right = 0;
    for (let x = w; x >= 1; x--) { if (isColEmpty(heatmap, objectCells, h, x)) right++; else break; }
    if (left + right > w) right = w - left;
    return { left, right, total: left + right };
}

function analyzeLevel(raw, heatmapEntry) {
    const { w, h } = raw.grid;
    const objectCells = collectObjectCells(raw);
    const heatmap = heatmapEntry.heatmap;

    const deadSquares = [];
    for (let y = 1; y <= h; y++) {
        for (let x = 1; x <= w; x++) {
            if (heatmap[y - 1][x - 1] === 0 && !objectCells.has(`${x},${y}`)) {
                deadSquares.push({ x, y });
            }
        }
    }

    const rows = countEmptyBorder(w, h, objectCells, heatmap, 'row');
    const cols = countEmptyBorder(w, h, objectCells, heatmap, 'col');
    const trimCandidate = rows.total > 0 && rows.total === cols.total;

    return {
        level: heatmapEntry.level,
        grid: { w, h },
        hintCount: heatmapEntry.hintCount,
        deadSquares,
        emptyBorder: { rows, cols },
        trimCandidate,
        suggestedGrid: trimCandidate ? { w: w - cols.total, h: h - rows.total } : null
    };
}

function main() {
    const asJson = process.argv.includes('--json');
    const rawLevels = loadJson('data/levels.json');
    const heatmaps = loadJson('data/level-heatmaps.json');

    const results = rawLevels.map((raw, i) => analyzeLevel(raw, heatmaps.levels[i]));

    if (asJson) {
        console.log(JSON.stringify(results, null, 2));
        return;
    }

    const withDead = results.filter(r => r.deadSquares.length > 0);
    const totalDead = withDead.reduce((sum, r) => sum + r.deadSquares.length, 0);
    console.log(`\n=== Dead squares (no hint visits, no grid object) ===`);
    console.log(`${withDead.length} of ${results.length} levels have at least one dead square; ${totalDead} dead squares total.\n`);
    for (const r of withDead) {
        const coords = r.deadSquares.map(c => `(${c.x},${c.y})`).join(' ');
        console.log(`Level ${r.level} [${r.grid.w}x${r.grid.h}, ${r.hintCount} hints] — ${r.deadSquares.length} dead: ${coords}`);
    }

    const trimmable = results.filter(r => r.trimCandidate);
    console.log(`\n=== Grid-trim candidates (equal empty border rows & columns) ===`);
    console.log(`${trimmable.length} of ${results.length} levels.\n`);
    for (const r of trimmable) {
        const { rows, cols } = r.emptyBorder;
        console.log(`Level ${r.level}: ${r.grid.w}x${r.grid.h} -> ${r.suggestedGrid.w}x${r.suggestedGrid.h} `
            + `(empty rows: top=${rows.top} bottom=${rows.bottom}; empty cols: left=${cols.left} right=${cols.right})`);
    }
}

main();
